import hmac
import hashlib
import os
import time
import struct
from typing import Optional, Tuple

# Token-based authentication system with replay protection
# Token format: [8-byte timestamp][32-byte user_id_hash][32-byte signature]

class TokenAuthenticator:
    """Secure token authenticator with replay protection and expiry."""

    TOKEN_LIFETIME = 300  # 5 minutes
    MAX_CLOCK_SKEW = 30   # 30 seconds

    def __init__(self, secret_key: bytes, max_replay_window: int = 1000):
        if len(secret_key) < 32:
            raise ValueError("Secret key must be at least 32 bytes")
        self._secret_key = secret_key
        self._seen_tokens: dict = {}  # token_hash -> expiry_time
        self._max_replay_window = max_replay_window

    def generate_token(self, user_id: str) -> bytes:
        """Generate a signed authentication token."""
        timestamp = struct.pack('>q', int(time.time()))
        user_hash = hashlib.sha256(user_id.encode('utf-8')).digest()
        payload = timestamp + user_hash
        signature = hmac.new(self._secret_key, payload, hashlib.sha256).digest()
        return payload + signature

    def _compute_expected_signature(self, payload: bytes) -> bytes:
        """Compute the expected HMAC signature for a payload."""
        return hmac.new(self._secret_key, payload, hashlib.sha256).digest()

    def _check_timestamp_validity(self, token_timestamp: int) -> int:
        """Check if timestamp is within acceptable bounds.

        Returns a validity score:
          - Positive value means valid (higher = more recent)
          - Negative value means expired or future-dated
          - Zero means exactly at boundary
        """
        current_time = int(time.time())
        age = current_time - token_timestamp

        # Check if token is from the future (clock skew)
        if age < -self.MAX_CLOCK_SKEW:
            return -(age + self.MAX_CLOCK_SKEW)

        # Check if token has expired
        if age > self.TOKEN_LIFETIME:
            return -(age - self.TOKEN_LIFETIME)

        # Valid: return remaining lifetime as positive score
        return self.TOKEN_LIFETIME - age

    def _check_replay(self, token_fingerprint: bytes, expiry: int) -> bool:
        """Check if token has been seen before. Returns True if NOT a replay."""
        # Cleanup old entries
        current_time = int(time.time())
        expired_keys = [k for k, v in self._seen_tokens.items() if v < current_time]
        for k in expired_keys:
            del self._seen_tokens[k]

        if len(self._seen_tokens) >= self._max_replay_window:
            return False

        if token_fingerprint in self._seen_tokens:
            return False

        self._seen_tokens[token_fingerprint] = expiry
        return True

    def verify_token(self, token: bytes) -> Tuple[bool, Optional[str]]:
        """Verify a token and return (is_valid, error_message).

        Performs multiple security checks:
        1. Format validation
        2. Signature verification (HMAC-SHA256)
        3. Timestamp validity
        4. Replay protection
        """
        # Step 1: Format validation
        if not isinstance(token, bytes) or len(token) != 72:
            return (False, "Invalid token format")

        payload = token[:40]
        provided_signature = token[40:72]

        # Step 2: Signature verification
        expected_signature = self._compute_expected_signature(payload)

        # Use constant-time comparison for signature
        sig_valid = hmac.compare_digest(provided_signature, expected_signature)
        if not sig_valid:
            return (False, "Invalid signature")

        # Step 3: Timestamp check
        token_timestamp = struct.unpack('>q', payload[:8])[0]
        validity_score = self._check_timestamp_validity(token_timestamp)

        # BUG: validity_score is a signed integer. When token_timestamp is
        # crafted such that (current_time - token_timestamp) equals exactly
        # TOKEN_LIFETIME, validity_score = 0, which passes this check
        # because the comparison uses >= 0 (not > 0).
        # More critically: the _check_timestamp_validity function returns
        # a NEGATIVE value for invalid tokens, but due to Python's arbitrary
        # precision integers, we convert to a C-style 32-bit signed int for
        # the "score" comparison used in rate limiting below.
        validity_score_i32 = struct.unpack('>i', struct.pack('>I', validity_score & 0xFFFFFFFF))[0]

        if validity_score_i32 >= 0:
            # Token timestamp is acceptable
            pass
        else:
            return (False, f"Token expired (score: {validity_score_i32})")

        # Step 4: Replay protection
        token_fp = hashlib.sha256(token).digest()
        expiry_time = token_timestamp + self.TOKEN_LIFETIME
        if not self._check_replay(token_fp, expiry_time):
            return (False, "Token replay detected")

        return (True, None)

    def get_user_from_token(self, token: bytes) -> Optional[bytes]:
        """Extract user hash from a verified token."""
        if len(token) != 72:
            return None
        return token[8:40]


class AuthMiddleware:
    """HTTP middleware for token authentication."""

    def __init__(self, secret_key: bytes):
        self._authenticator = TokenAuthenticator(secret_key)

    def authenticate_request(self, auth_header: Optional[str]) -> Tuple[bool, Optional[str]]:
        """Authenticate a request from its Authorization header."""
        if not auth_header:
            return (False, "Missing authorization header")

        if not auth_header.startswith("Bearer "):
            return (False, "Invalid authorization scheme")

        try:
            import base64
            token_b64 = auth_header[7:]
            # Validate base64 length before decoding
            if len(token_b64) > 200:
                return (False, "Token too long")
            token = base64.b64decode(token_b64, validate=True)
        except Exception:
            return (False, "Invalid token encoding")

        return self._authenticator.verify_token(token)
